static void dfs(struct TreeNode *node, int remain, int *path, int depth,
                int ***res, int *returnSize, int **colSizes, int *capacity) {
  if (node == NULL) return;
  path[depth] = node->val;
  remain -= node->val;
  if (node->left == NULL && node->right == NULL) {
    if (remain == 0) {
      if (*returnSize == *capacity) {
        *capacity = *capacity ? *capacity * 2 : 8;
        *res = (int **)realloc(*res, sizeof(int *) * (*capacity));
        *colSizes = (int *)realloc(*colSizes, sizeof(int) * (*capacity));
      }
      int *row = (int *)malloc(sizeof(int) * (depth + 1));
      for (int i = 0; i <= depth; i++) row[i] = path[i];
      (*res)[*returnSize] = row;
      (*colSizes)[*returnSize] = depth + 1;
      (*returnSize)++;
    }
    return;
  }
  dfs(node->left, remain, path, depth + 1, res, returnSize, colSizes, capacity);
  dfs(node->right, remain, path, depth + 1, res, returnSize, colSizes, capacity);
}

int **pathSum(struct TreeNode *root, int targetSum, int *returnSize, int **returnColumnSizes) {
  int **res = NULL;
  int *colSizes = NULL;
  int capacity = 0;
  int path[5001];
  *returnSize = 0;
  dfs(root, targetSum, path, 0, &res, returnSize, &colSizes, &capacity);
  *returnColumnSizes = colSizes;
  return res;
}

class Solution {
  void dfs(TreeNode *node, int remain, vector<int> &path, vector<vector<int>> &res) {
    if (!node) return;
    path.push_back(node->val);
    remain -= node->val;
    if (!node->left && !node->right) {
      if (remain == 0) res.push_back(path);
    } else {
      dfs(node->left, remain, path, res);
      dfs(node->right, remain, path, res);
    }
    path.pop_back();
  }

public:
  vector<vector<int>> pathSum(TreeNode *root, int targetSum) {
    vector<vector<int>> res;
    vector<int> path;
    dfs(root, targetSum, path, res);
    return res;
  }
};

func pathSum(root *TreeNode, targetSum int) [][]int {
	res := [][]int{}
	var dfs func(node *TreeNode, remain int, path []int)
	dfs = func(node *TreeNode, remain int, path []int) {
		if node == nil {
			return
		}
		path = append(path, node.Val)
		remain -= node.Val
		if node.Left == nil && node.Right == nil {
			if remain == 0 {
				cur := make([]int, len(path))
				copy(cur, path)
				res = append(res, cur)
			}
			return
		}
		dfs(node.Left, remain, path)
		dfs(node.Right, remain, path)
	}
	dfs(root, targetSum, []int{})
	return res
}

class TreeNode {
  int val;
  TreeNode left;
  TreeNode right;

  TreeNode(int x) {
    val = x;
  }
}

class Solution {
  private void dfs(TreeNode node, int remain, List<Integer> path, List<List<Integer>> res) {
    if (node == null) {
      return;
    }
    path.add(node.val);
    remain -= node.val;
    if (node.left == null && node.right == null) {
      if (remain == 0) {
        res.add(new ArrayList<>(path));
      }
    } else {
      dfs(node.left, remain, path, res);
      dfs(node.right, remain, path, res);
    }
    path.remove(path.size() - 1);
  }

  public List<List<Integer>> pathSum(TreeNode root, int targetSum) {
    List<List<Integer>> res = new ArrayList<>();
    dfs(root, targetSum, new ArrayList<>(), res);
    return res;
  }
}

class Solution:
    def pathSum(self, root: Optional[TreeNode], targetSum: int) -> List[List[int]]:
        res: List[List[int]] = []
        path: List[int] = []

        def dfs(node, remain):
            if node is None:
                return
            path.append(node.val)
            remain -= node.val
            if node.left is None and node.right is None:
                if remain == 0:
                    res.append(path[:])
            else:
                dfs(node.left, remain)
                dfs(node.right, remain)
            path.pop()

        dfs(root, targetSum)
        return res

impl Solution {
  pub fn path_sum(root: Option<Box<TreeNode>>, target_sum: i32) -> Vec<Vec<i32>> {
    fn dfs(
      node: &Option<Box<TreeNode>>,
      remain: i32,
      path: &mut Vec<i32>,
      res: &mut Vec<Vec<i32>>,
    ) {
      if let Some(n) = node {
        path.push(n.val);
        let rest = remain - n.val;
        if n.left.is_none() && n.right.is_none() {
          if rest == 0 {
            res.push(path.clone());
          }
        } else {
          dfs(&n.left, rest, path, res);
          dfs(&n.right, rest, path, res);
        }
        path.pop();
      }
    }

    let mut res = Vec::new();
    let mut path = Vec::new();
    dfs(&root, target_sum, &mut path, &mut res);
    res
  }
}

const pathSum = (root: TreeNode | null, targetSum: number): number[][] => {
  const res: number[][] = [];
  const path: number[] = [];
  const dfs = (node: TreeNode | null, remain: number): void => {
    if (node === null) return;
    path.push(node.val);
    remain -= node.val;
    if (node.left === null && node.right === null) {
      if (remain === 0) res.push(path.slice());
    } else {
      dfs(node.left, remain);
      dfs(node.right, remain);
    }
    path.pop();
  };
  dfs(root, targetSum);
  return res;
};
